 else {if($dueOnly&&$filter==='Closed')throw new RuntimeException('Closed enquiries are excluded from follow-ups. Choose another status.');if($filter!==''&&!in_array($filter,['New','Contacted','Closed'],true))throw new RuntimeException('Choose a valid status.');$today=(new DateTimeImmutable('now',new DateTimeZone($b['time_zone'])))->format('Y-m-d');$dueQuery=$dueOnly?'&follow_up_on=lte.'.$today.($filter===''?'&status=neq.Closed':''):'';$rows=api($prefix.$dueQuery.($filter!==''?'&status=eq.'.rawurlencode($filter):'').'&select=id,customer_name,service_name,status,created_at,follow_up_on&order='.($dueOnly?'follow_up_on.asc,created_at.asc,id.asc':'created_at.desc,id.desc').'&limit=21&offset='.(($page-1)*20),[],'GET',$_SESSION['auth']['access_token']);}
