tes">Private notes</label><textarea id="private_notes" name="private_notes" rows="4" maxlength="2000"><?=esc(is_string($_POST['private_notes']??null)?$_POST['private_notes']:($detail['private_notes']??''))?></textarea><small>Only your business can see these notes. They are never copied into customer quotes or emails.</small><label for="follow_up_on">Follow-up date</label><input id="follow_up_on" name="follow_up_on" type="date" min="2000-01-01" max="2099-12-31" value="<?=esc(is_string($_POST['follow_up_on']??null)?$_POST['follow_up_on']:($detail['follow_up_on']??''))?>"><small>Date in <?=esc(str_replace('_',' ',$b['time_zone']))?>. Leave blank to clear. Closed enquiries stay out of the due list.</small><button class="button">Save enquiry</button></form><?php enquiry_workspace_render($detail,$workspace,$b,$activityPage);?></article>
